import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import API from "../services/adminApi";
import "../styles/ProviderDetails.css";

const ProviderDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [data, setData] = useState(null);

  useEffect(() => {
    const fetchDetails = async () => {
      const res = await API.get(`/provider-details/${id}`);
      setData(res.data);
    };
    fetchDetails();
  }, [id]);

  if (!data || !data.profile) return <p>Loading...</p>;

const { profile, skills = [], reviews = [], ratingSummary = {} } = data;

  return (
    <div className="details-container">

      <button onClick={() => navigate(-1)} className="back-btn">
        ← Back to List
      </button>

      <h2>{profile.name}</h2>
      <p className="sub-text">{profile.location}</p>

      <div className="grid">

        {/* CONTACT */}
        <div className="card">
          <h3>Contact</h3>
          <p>Email: {profile.email}</p>
          <p>Phone: {profile.phone}</p>
          <p>Applied: {new Date(profile.created_at).toLocaleDateString()}</p>
        </div>

        {/* WORK DETAILS */}
        <div className="card">
          <h3>Work Details</h3>
          <p>Experience: {profile.experience} yrs</p>
          <p>Availability: {profile.availability_status}</p>
          <p>Verification: {profile.verification_status}</p>
        </div>

        {/* DESCRIPTION */}
        <div className="card">
          <h3>About</h3>
          <p>{profile.description}</p>
        </div>

        {/* SKILLS */}
        <div className="card">
          <h3>Skills</h3>
          {skills.map((skill, index) => (
            <div key={index} className="skill-item">
              <strong>{skill.skill_name}</strong>
              <p>Category: {skill.category}</p>
              <p>Price: ₹{skill.price}</p>
              <p>Duration: {skill.duration}</p>
            </div>
          ))}
        </div>

        {/* RATINGS */}
        <div className="card">
          <h3>Ratings</h3>
          <p>
            ⭐ {ratingSummary.avg_rating || 0} 
            ({ratingSummary.total_reviews} reviews)
          </p>
        </div>

        {/* REVIEWS */}
        <div className="card">
          <h3>Reviews</h3>
          {reviews.map((r, i) => (
            <div key={i}>
              <p>⭐ {r.rating}</p>
              <p>{r.review_comment}</p>
            </div>
          ))}
        </div>

      </div>

    </div>
  );
};

export default ProviderDetails;
